/**
 * src/utils/minifier.ts
 * Strips comments, collapses whitespace, and safely prepares JavaScript
 * for single-file HTML export. Designed specifically for the self-contained
 * runtime generated by exporter.ts (large IIFE with template literals).
 * Includes input validation and a size calculator used for the export badge.
 */

export function minifyJS(code: string): string {
  if (typeof code !== 'string') {
    throw new Error('minifyJS() expects a string of JavaScript code');
  }

  if (code.trim().length === 0) {
    throw new Error('minifyJS() cannot process empty code');
  }

  let minified = code
    // Remove multi-line comments (including /* ... */)
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    // Remove single-line comments (// ...). This is safe for our generated runtime
    // because there are no URLs or regex with // in the exported template.
    .replace(/\/\/.*$/gm, ' ');

  // Collapse all whitespace (newlines, tabs, multiple spaces) into a single space.
  // This dramatically reduces size while preserving JS validity for our IIFE.
  minified = minified.replace(/\s+/g, ' ');

  // Remove unnecessary whitespace around operators, brackets, and punctuation.
  // The regex is deliberately conservative to avoid breaking template literals
  // or object literals that appear in the runtime.
  minified = minified
    .replace(/\s*([,;:{}()[\]=+\-*/%<>!&|?:])\s*/g, '$1')
    .replace(/\s+\./g, '.')
    .replace(/\.\s+/g, '.');

  // Re-add minimal whitespace after keywords that require it to remain valid JS
  minified = minified
    .replace(/function\(/g, 'function (')
    .replace(/return\s+/g, 'return ')
    .replace(/else\s*\{/g, 'else {')
    .replace(/if\s*\(/g, 'if (');

  const result = minified.trim();

  if (result.length === 0) {
    throw new Error('minifyJS() produced empty output – check input');
  }

  return result;
}

/**
 * Returns the size of an exported HTML file in kilobytes (rounded).
 * Used both internally by the exporter and for the on-page info badge.
 */
export function calculateSize(html: string): number {
  if (typeof html !== 'string') {
    throw new Error('calculateSize() expects an HTML string');
  }

  if (html.length === 0) {
    return 0;
  }

  // Round to nearest integer KB (matches usage in exporter.ts)
  return Math.round(html.length / 1024);
}
